Question:
あなたは以下のツールを使うことができます。
[
    {
        "type":"function",
        "function": {
            "name": "get_stock_symbol",
            "description": "会社名から株取引市場でのシンボルを取得する",
            "parameters": {
                "type": "object",
                "properties": {
                    "company_name": {
                        "type": "string",
                        "description": "会社名"
                    },
                },
                "required": ["company_name"]
            }
